import { IntegerColumn, ReferenceColumn, StringColumn, Table } from '@servicenow/sdk/core'

export const sn_table_app_incoming = Table({
    actions: ['read', 'update', 'create'],
    index: [{ name: 'index', element: 'string_column', unique: false }],
    name: 'sn_table_app_incoming',
    label: 'Incoming Table',
    extends: 'cmdb',
    schema: {
        string_column: StringColumn({
            dropdown: 'none',
            choices: {
                choice1: { label: 'choice1' },
                choice2: { label: 'choice2' },
            },
        }),
        integer_column: IntegerColumn({
            label: 'Integer Column',
            audit: true,
            dropdown: 'suggestion',
            choices: {
                1: { label: 'One' },
                2: { label: 'Two' },
            },
        }),
        reference_column: ReferenceColumn({ referenceTable: 'task' }),
    },
    display: 'integer_column',
    attributes: {
        live_feed: true,
    },
})
